```python
shopping_list = []

def add_item():
    """Add an item to the shopping list."""
    item = input("Add an item to the shopping list: ")
    shopping_list.append(item)
    print(f"{len(shopping_list)}. {item}")

def remove_item():
    """Remove an item from the shopping list."""
    if shopping_list:
        item_index = int(input("Enter the index of the item to remove (1-based): ")) - 1
        if item_index < len(shopping_list):
            del shopping_list[item_index]
            print(f"Item removed: {shopping_list[item_index]}")
        else:
            print("Invalid index. Please try again.")
    else:
        print("Shopping list is empty. Add some items first.")

def view_list():
    """Display all items in the shopping list."""
    if shopping_list:
        print("\nShopping List:")
        for i, item in enumerate(shopping_list, start=1):
            print(f"{i}. {item}")
    else:
        print("Shopping list is empty.")

def main():
    while True:
        print("\n1. Add an item\n2. Remove an item\n3. View the list\n4. Quit")
        choice = int(input("Enter your choice: "))

        if choice == 1:
            add_item()
        elif choice == 2:
            remove_item()
        elif choice == 3:
            view_list()
        elif choice == 4:
            print("Goodbye!")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

This program allows the user to add items, remove items, and view the shopping list. The user interface is simple and easy to understand.
